cat > Kconfig <<'EOF'
#
# For a description of the syntax of this configuration file,
# see the file kconfig-language.txt in the NuttX tools repository.
#

config LVX_MIIO
	bool "miio LAN client"
	default n
	depends on NET_UDP
	select CRYPTO_MBEDTLS
	---help---
		Controls a Mi Home device on the LAN with the miio protocol and
		adds the NSH command "miio get".  The device IP and token are
		read from /tmp/miio.conf at run time.
EOF
cat > Make.defs <<'EOF'
############################################################################
# app/miio/Make.defs
############################################################################

ifneq ($(CONFIG_LVX_MIIO),)
CONFIGURED_APPS += $(patsubst %/,%,$(dir $(lastword $(MAKEFILE_LIST))))
endif
EOF
cat > Makefile <<'EOF'
############################################################################
# app/miio/Makefile
############################################################################

include $(APPDIR)/Make.defs

PROGNAME  = miio
PRIORITY  = SCHED_PRIORITY_DEFAULT
STACKSIZE = 8192
MODULE    = $(CONFIG_LVX_MIIO)

CSRCS   = miio.c
MAINSRC = miio_main.c

include $(APPDIR)/Application.mk
EOF
cat > CMakeLists.txt <<'EOF'
# app/miio/CMakeLists.txt
if(CONFIG_LVX_MIIO)
  nuttx_add_application(
    NAME miio
    SRCS miio_main.c miio.c
    DEPENDS mbedtls
    STACKSIZE 8192)
endif()
EOF
