/****************************************************************************
 * app/miio/miio_main.c
 *
 * miio get: power, mode, target temperature and load power of the Mi Home
 * AC partner configured in /tmp/miio.conf.
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "miio.h"

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static int miio_get(FAR struct miio_s *m)
{
  char buf[512];
  char power[8];
  char mode[16];
  FAR char *p;
  FAR char *q;
  int temp;
  int ret;

  ret = miio_call(m, "get_prop", "[\"power\",\"mode\",\"tar_temp\","
                  "\"far_level\",\"ver_swing\",\"load_power\"]",
                  buf, sizeof(buf));
  if (ret < 0)
    {
      return ret;
    }

  /* e.g. {"result":["on","cool",25,"","on",202.00],"id":1} */

  p = strstr(buf, "\"result\":[");
  q = p != NULL ? strchr(p, ']') : NULL;
  if (q == NULL || sscanf(p + 10, "\"%7[^\"]\",\"%15[^\"]\",%d",
                          power, mode, &temp) != 3)
    {
      printf("miio: unexpected reply %s\n", buf);
      return -EBADMSG;
    }

  *q = '\0';
  printf("power:      %s\n", power);
  printf("mode:       %s\n", mode);
  printf("tar_temp:   %d\n", temp);
  printf("load_power: %.2f W\n", strtod(strrchr(p, ',') + 1, NULL));
  return 0;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int main(int argc, FAR char *argv[])
{
  struct miio_s m;
  int ret;

  if (argc != 2 || strcmp(argv[1], "get") != 0)
    {
      printf("Usage: %s get\n", argv[0]);
      return EXIT_FAILURE;
    }

  ret = miio_open(&m, MIIO_CONF);
  if (ret == -ENOENT)
    {
      printf("miio: not configured, no %s\n", MIIO_CONF);
      return EXIT_FAILURE;
    }
  else if (ret < 0)
    {
      printf("miio: bad %s: %d\n", MIIO_CONF, ret);
      return EXIT_FAILURE;
    }

  ret = miio_get(&m);
  if (ret == -ETIMEDOUT)
    {
      printf("miio: no reply, device offline or wrong token\n");
    }
  else if (ret == -EBADMSG)
    {
      printf("miio: reply does not decrypt, wrong token?\n");
    }
  else if (ret < 0)
    {
      printf("miio: get_prop failed: %d\n", ret);
    }

  miio_close(&m);
  return ret < 0 ? EXIT_FAILURE : EXIT_SUCCESS;
}
EOF

