/****************************************************************************
 * Private Functions
 ****************************************************************************/

static int miio_get(FAR struct miio_s *m)
{
  FAR char *v[6];
  char buf[512];
  int ret;

  ret = miio_get_prop(m, "[\"power\",\"mode\",\"tar_temp\","
                      "\"far_level\",\"ver_swing\",\"load_power\"]",
                      6, buf, sizeof(buf), v);
  if (ret < 0)
    {
      return ret;
    }

  printf("power:      %s\n", v[0]);
  printf("mode:       %s\n", v[1]);
  printf("tar_temp:   %s\n", v[2]);
  printf("load_power: %s W\n", v[5]);
  return 0;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int main(int argc, FAR char *argv[])
{
  struct miio_s m;
  int ret;

  if (argc != 2 || strcmp(argv[1], "get") != 0)
    {
      printf("Usage: %s get\n", argv[0]);
      return EXIT_FAILURE;
    }

  ret = miio_open(&m, MIIO_CONF);
  if (ret == -ENOENT)
    {
      printf("miio: not configured, no %s\n", MIIO_CONF);
      return EXIT_FAILURE;
    }
  else if (ret < 0)
    {
      printf("miio: bad %s: %d\n", MIIO_CONF, ret);
      return EXIT_FAILURE;
    }

  ret = miio_get(&m);
  if (ret == -ETIMEDOUT)
    {
      printf("miio: no reply, device offline or wrong token\n");
    }
  else if (ret == -EBADMSG)
    {
      printf("miio: reply does not decrypt, wrong token?\n");
    }
  else if (ret == -EPROTO)
    {
      printf("miio: unexpected get_prop reply\n");
    }
  else if (ret < 0)
    {
      printf("miio: get_prop failed: %d\n", ret);
    }

  miio_close(&m);
  return ret < 0 ? EXIT_FAILURE : EXIT_SUCCESS;
}

