static int aircon_start(lv_nuttx_result_t *result)
{
  lv_nuttx_dsc_t info;

  lv_init();

  lv_nuttx_dsc_init(&info);
  lv_nuttx_init(&info, result);

  if (result->disp == NULL || result->indev == NULL)
    {
      fprintf(stderr, "aircon: no display or touchscreen\n");
      return -1;
    }

  ui_hide_perf();

  aircon_create();
  return 0;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int main(int argc, FAR char *argv[])
{
  lv_nuttx_result_t result;
  pthread_attr_t attr;
  pthread_t thread;
  uint32_t idle;

  UNUSED(argc);
  UNUSED(argv);

  /* LVGL is one global instance, shared by every task of the flat build */

  if (lv_is_initialized())
    {
      fprintf(stderr, "aircon: LVGL is busy, start it from the "
              "launcher\n");
      return 1;
    }

  memset(&g_state, 0, sizeof(g_state));
  memset(&g_shown, 0, sizeof(g_shown));
  g_request = 0;
  g_shown_request = 0;
  g_shown_on = false;

  g_running = aircon_start(&result) == 0;
  if (!g_running)
    {
      lv_nuttx_deinit(&result);
      lv_deinit();
      return 1;
    }

  pthread_attr_init(&attr);
  pthread_attr_setstacksize(&attr, 8192);
  if (pthread_create(&thread, &attr, aircon_thread, NULL) != 0)
    {
      g_running = false;
    }

  while (g_running)
    {
      idle = lv_timer_handler();
      usleep(MAX(idle, 1) * 1000);
    }

  /* The thread sees g_running within 100 ms, or after at most two 2 s
   * timeouts while the device does not answer
   */

  pthread_join(thread, NULL);
  lv_nuttx_deinit(&result);
  lv_deinit();
  return 0;
}

