/****************************************************************************
 * app/mihome/mihome.h
 *
 * Mi Home device control for the apps: read the state, switch on and off,
 * set the temperature.  What to call on which model comes from a table in
 * mihome.c, the device is reached with the miio protocol (app/miio).
 ****************************************************************************/

#ifndef __APP_MIHOME_MIHOME_H
#define __APP_MIHOME_MIHOME_H

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <stdbool.h>

#include "miio.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* Fields of struct mihome_state_s that the model has */

#define MIHOME_POWER          (1 << 0)
#define MIHOME_MODE           (1 << 1)
#define MIHOME_TEMP           (1 << 2)
#define MIHOME_LOAD           (1 << 3)

/****************************************************************************
 * Public Types
 ****************************************************************************/

struct mihome_model_s;

struct mihome_s
{
  FAR const struct mihome_model_s *model;   /* NULL until opened */
  struct miio_s miio;
};

struct mihome_state_s
{
  FAR const char *model;
  unsigned int fields;      /* MIHOME_* */
  bool on;
  int temp;                 /* Target, degree C */
  int load;                 /* W */
  int run_load;             /* Load above which it really runs, 0 if none */
  char mode[16];            /* e.g. "cool" */
};

/****************************************************************************
 * Public Function Prototypes
 ****************************************************************************/

/* A closed handle, every call opens it when needed */

void mihome_init(FAR struct mihome_s *h);
void mihome_close(FAR struct mihome_s *h);

/* All return 0 or a negated errno:
 *   -ENOENT, -EINVAL   no or a malformed MIIO_CONF
 *   -ENOTSUP           model in MIIO_CONF not in the table, or a field it
 *                      does not have
 *   -ETIMEDOUT, ...    errors of miio_call(), the device is offline
 *   -EPROTO            a reply that does not fit the model
 */

int mihome_get(FAR struct mihome_s *h, FAR struct mihome_state_s *s);

/* Some models (the AC partner) set their own temperature when switched
 * on, mihome_power() sets the one from before again.
 */

int mihome_power(FAR struct mihome_s *h, bool on);
int mihome_temp(FAR struct mihome_s *h, int temp);

#endif /* __APP_MIHOME_MIHOME_H */

/****************************************************************************
 * app/mihome/mihome.c
 *
 * Model table and the calls built from it.  Older miio devices (the AC
 * partner) read properties by name with get_prop and have a method per
 * setting; MIoT devices read and write properties by service and property
 * id with get_properties / set_properties:
 *
 *   get_prop        ["power","tar_temp"]                -> ["on",25]
 *   set_power       ["on"]                              -> ["ok"]
 *   get_properties  [{"did":"power","siid":2,"piid":1}]
 *                   -> [{"did":"power","siid":2,"piid":1,"code":0,
 *                        "value":true}]
 *   set_properties  [{"did":"power","siid":2,"piid":1,"value":true}]
 *                   -> [{"did":"power","siid":2,"piid":1,"code":0}]
 *
 * The device sends "did" back as it got it, the property name is used.
 * No MIoT model is in the table yet, that part has not run on a device.
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <sys/param.h>

#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "mihome.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* Index in mihome_model_s.prop, also the bit of the MIHOME_* field */

#define PROP_POWER            0
#define PROP_MODE             1
#define PROP_TEMP             2
#define PROP_LOAD             3
#define PROP_COUNT            4

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct mihome_prop_s
{
  FAR const char *name;     /* NULL if the model does not have it */
  uint8_t siid;             /* MIoT only */
  uint8_t piid;
};

struct mihome_model_s
{
  FAR const char *model;
  bool miot;
  struct mihome_prop_s prop[PROP_COUNT];
  FAR const char *set_power;  /* miio methods */
  FAR const char *set_temp;
  bool power_sets_temp;       /* Switching on changes the temperature */
  int run_load;
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

/* The first entry is used when MIIO_CONF names no model */

static const struct mihome_model_s g_models[] =
{
  /* AC partner 2, docs/miio/README.md 4.3: on sets 20 degree C, below
   * about 60 W the compressor does not run
   */

  {
    "lumi.acpartner.mcn02", false,
    {
      { "power" }, { "mode" }, { "tar_temp" }, { "load_power" }
    },
    "set_power", "set_tar_temp", true, 60
  },
};

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static int mihome_open(FAR struct mihome_s *h)
{
  int ret;
  int i;

  if (h->model != NULL)
    {
      return 0;
    }

  ret = miio_open(&h->miio, MIIO_CONF);
  if (ret < 0)
    {
      return ret;
    }

  for (i = 0; i < nitems(g_models); i++)
    {
      if (h->miio.model[0] == '\0' ||
          strcmp(h->miio.model, g_models[i].model) == 0)
        {
          h->model = &g_models[i];
          return 0;
        }
    }

  miio_close(&h->miio);
  return -ENOTSUP;
}

static int mihome_call(FAR struct mihome_s *h, FAR const char *method,
                       FAR const char *params, FAR char *buf, size_t len)
{
  return miio_call(&h->miio, method, params, buf, len);
}

/* Point v at the n values of the result, strings without their quotes */

static int mihome_values(FAR char *buf, bool miot, FAR char **v, int n)
{
  FAR char *p = strstr(buf, "\"result\":[");
  FAR char *q = p != NULL ? strchr(p, ']') : NULL;
  int i;

  if (q == NULL)
    {
      return -EPROTO;
    }

  *q = '\0';
  p += 10;
  for (i = 0; i < n && p != NULL; i++)
    {
      if (miot)
        {
          p = strstr(p, "\"value\":");
          if (p == NULL)
            {
              break;
            }

          v[i] = p + 8;
          p = v[i] + strcspn(v[i], ",}");
          if (*p != '\0')
            {
              *p++ = '\0';
            }
        }
      else
        {
          v[i] = strsep(&p, ",");
        }

      if (*v[i] == '"')
        {
          v[i]++;
          v[i][strcspn(v[i], "\"")] = '\0';
        }
    }

  return i == n ? 0 : -EPROTO;
}

/* Write one property, value is JSON */

static int mihome_set(FAR struct mihome_s *h, int prop,
                      FAR const char *value)
{
  FAR const struct mihome_model_s *mo = h->model;
  FAR const struct mihome_prop_s *pr = &mo->prop[prop];
  char params[128];
  char buf[256];
  int ret;

  if (pr->name == NULL)
    {
      return -ENOTSUP;
    }

  if (mo->miot)
    {
      snprintf(params, sizeof(params),
               "[{\"did\":\"%s\",\"siid\":%d,\"piid\":%d,\"value\":%s}]",
               pr->name, pr->siid, pr->piid, value);
    }
  else
    {
      snprintf(params, sizeof(params), "[%s]", value);
    }

  ret = mihome_call(h, mo->miot ? "set_properties" :
                       prop == PROP_POWER ? mo->set_power : mo->set_temp,
                    params, buf, sizeof(buf));
  if (ret < 0)
    {
      return ret;
    }

  return strstr(buf, mo->miot ? "\"code\":0" : "\"ok\"") != NULL ?
         0 : -EPROTO;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

void mihome_init(FAR struct mihome_s *h)
{
  h->model = NULL;
}

void mihome_close(FAR struct mihome_s *h)
{
  if (h->model != NULL)
    {
      miio_close(&h->miio);
      h->model = NULL;
    }
}

int mihome_get(FAR struct mihome_s *h, FAR struct mihome_state_s *s)
{
  FAR const struct mihome_model_s *mo;
  FAR const struct mihome_prop_s *pr;
  FAR char *v[PROP_COUNT];
  int prop[PROP_COUNT];
  char params[256];
  char buf[512];
  size_t len;
  int ret;
  int n;
  int i;

  ret = mihome_open(h);
  if (ret < 0)
    {
      return ret;
    }

  /* Ask for the properties the model has */

  mo = h->model;
  len = snprintf(params, sizeof(params), "[");
  for (i = n = 0; i < PROP_COUNT; i++)
    {
      pr = &mo->prop[i];
      if (pr->name == NULL)
        {
          continue;
        }

      if (mo->miot)
        {
          len += snprintf(params + len, sizeof(params) - len,
                          "%s{\"did\":\"%s\",\"siid\":%d,\"piid\":%d}",
                          n > 0 ? "," : "", pr->name, pr->siid, pr->piid);
        }
      else
        {
          len += snprintf(params + len, sizeof(params) - len, "%s\"%s\"",
                          n > 0 ? "," : "", pr->name);
        }

      prop[n++] = i;
    }

  snprintf(params + len, sizeof(params) - len, "]");

  ret = mihome_call(h, mo->miot ? "get_properties" : "get_prop", params,
                    buf, sizeof(buf));
  if (ret >= 0)
    {
      ret = mihome_values(buf, mo->miot, v, n);
    }

  if (ret < 0)
    {
      return ret;
    }

  memset(s, 0, sizeof(*s));
  s->model = mo->model;
  s->run_load = mo->run_load;
  for (i = 0; i < n; i++)
    {
      s->fields |= 1 << prop[i];
      switch (prop[i])
        {
          case PROP_POWER:
            s->on = strcmp(v[i], "on") == 0 || strcmp(v[i], "true") == 0;
            break;

          case PROP_MODE:
            strlcpy(s->mode, v[i], sizeof(s->mode));
            break;

          case PROP_TEMP:
            s->temp = atoi(v[i]);
            break;

          case PROP_LOAD:
            s->load = strtod(v[i], NULL) + 0.5;
            break;
        }
    }

  return 0;
}

int mihome_power(FAR struct mihome_s *h, bool on)
{
  struct mihome_state_s s;
  int ret;

  /* The temperature to set again, and opens the device */

  ret = mihome_get(h, &s);
  if (ret < 0)
    {
      return ret;
    }

  ret = mihome_set(h, PROP_POWER, h->model->miot ? (on ? "true" : "false") :
                                  on ? "\"on\"" : "\"off\"");
  if (ret == 0 && on && h->model->power_sets_temp &&
      (s.fields & MIHOME_TEMP) != 0)
    {
      ret = mihome_temp(h, s.temp);
    }

  return ret;
}

int mihome_temp(FAR struct mihome_s *h, int temp)
{
  char value[8];
  int ret;

  ret = mihome_open(h);
  if (ret < 0)
    {
      return ret;
    }

  snprintf(value, sizeof(value), "%d", temp);
  return mihome_set(h, PROP_TEMP, value);
}

