/****************************************************************************
 * app/mihome/mihome_main.c
 *
 * NSH command miio: state of the Mi Home device in MIIO_CONF, switch it
 * on and off, set its temperature.
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "mihome.h"

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static void mihome_print(FAR const struct mihome_state_s *s)
{
  printf("model:      %s\n", s->model);
  if (s->fields & MIHOME_POWER)
    {
      printf("power:      %s\n", s->on ? "on" : "off");
    }

  if (s->fields & MIHOME_MODE)
    {
      printf("mode:       %s\n", s->mode);
    }

  if (s->fields & MIHOME_TEMP)
    {
      printf("tar_temp:   %d\n", s->temp);
    }

  if (s->fields & MIHOME_LOAD)
    {
      printf("load_power: %d W\n", s->load);
    }
}

static void mihome_error(int ret)
{
  switch (ret)
    {
      case -ENOENT:
        printf("miio: not configured, no %s\n", MIIO_CONF);
        break;

      case -EINVAL:
        printf("miio: bad %s\n", MIIO_CONF);
        break;

      case -ENOTSUP:
        printf("miio: model not supported\n");
        break;

      case -ETIMEDOUT:
        printf("miio: no reply, device offline or wrong token\n");
        break;

      case -EBADMSG:
        printf("miio: reply does not decrypt, wrong token?\n");
        break;

      case -EPROTO:
        printf("miio: unexpected reply\n");
        break;

      default:
        printf("miio: failed: %d\n", ret);
        break;
    }
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int main(int argc, FAR char *argv[])
{
  struct mihome_state_s s;
  struct mihome_s h;
  int ret;

  if (argc == 2 && strcmp(argv[1], "on") == 0)
    {
      mihome_init(&h);
      ret = mihome_power(&h, true);
    }
  else if (argc == 2 && strcmp(argv[1], "off") == 0)
    {
      mihome_init(&h);
      ret = mihome_power(&h, false);
    }
  else if (argc == 3 && strcmp(argv[1], "temp") == 0)
    {
      mihome_init(&h);
      ret = mihome_temp(&h, atoi(argv[2]));
    }
  else if (argc == 2 && strcmp(argv[1], "get") == 0)
    {
      mihome_init(&h);
      ret = 0;
    }
  else
    {
      printf("Usage: %s get | on | off | temp <degree C>\n", argv[0]);
      return EXIT_FAILURE;
    }

  /* Every command ends with the state it left */

  if (ret == 0)
    {
      ret = mihome_get(&h, &s);
    }

  if (ret == 0)
    {
      mihome_print(&s);
    }
  else
    {
      mihome_error(ret);
    }

  mihome_close(&h);
  return ret < 0 ? EXIT_FAILURE : EXIT_SUCCESS;
}
