static int g_real_calls;

int miio_open(FAR struct miio_s *m, FAR const char *conf)
{
  return -ENOENT;
}

void miio_close(FAR struct miio_s *m)
{
}

int miio_call(FAR struct miio_s *m, FAR const char *method,
              FAR const char *params, FAR char *buf, size_t len)
{
  g_real_calls++;
  return -ETIMEDOUT;
}

static void show(const char *what, struct mihome_state_s *s)
{
  printf("%-28s mock=%d on=%d temp=%d load=%d mode=%s fields=%x\n", what,
         s->mock, s->on, s->temp, s->load, s->mode, s->fields);
}

int main(void)
{
  struct mihome_state_s s;
  struct mihome_s h;
  FAR char *v[4];
  char buf[256];

  /* Parsing, miio and MIoT replies */

  strcpy(buf, "{\"id\":1,\"result\":[\"on\",\"cool\",25,177.00],\"exe_time\":4}");
  assert(mihome_values(buf, false, v, 4) == 0);
  assert(!strcmp(v[0], "on") && !strcmp(v[1], "cool") &&
         !strcmp(v[2], "25") && !strcmp(v[3], "177.00"));
  strcpy(buf, "{\"id\":1,\"result\":[\"on\",\"cool\"]}");
  assert(mihome_values(buf, false, v, 4) == -EPROTO);
  strcpy(buf, "{\"id\":1,\"error\":{\"code\":-5001}}");
  assert(mihome_values(buf, false, v, 1) == -EPROTO);
  strcpy(buf, "{\"id\":2,\"result\":[{\"did\":\"power\",\"siid\":2,\"piid\":1,"
              "\"code\":0,\"value\":true},{\"did\":\"load\",\"siid\":11,"
              "\"piid\":2,\"code\":0,\"value\":12.5}]}");
  assert(mihome_values(buf, true, v, 2) == 0);
  assert(!strcmp(v[0], "true") && !strcmp(v[1], "12.5"));
  printf("parse ok\n");

  /* Auto without the config is the mock */

  assert(access(MIIO_CONF, F_OK) != 0);
  mihome_init(&h);
  assert(mihome_get(&h, &s) == 0 && s.mock && s.on && s.temp == 25);
  assert(s.load >= 267 && s.load <= 273);
  show("start", &s);

  assert(mihome_temp(&h, 22) == 0 && mihome_get(&h, &s) == 0);
  show("temp 22", &s);
  assert(s.temp == 22 && s.load >= 357 && s.load <= 363);
  assert(mihome_temp(&h, 40) == -EPROTO);

  assert(mihome_power(&h, false) == 0 && mihome_get(&h, &s) == 0);
  show("off", &s);
  assert(!s.on && s.load >= 93 && s.load <= 99);
  sleep(16);
  assert(mihome_get(&h, &s) == 0);
  show("off +16 s", &s);
  assert(s.load >= 21 && s.load <= 27);

  /* On sets 20, mihome_power() sets 22 again */

  assert(mihome_power(&h, true) == 0 && mihome_get(&h, &s) == 0);
  show("on", &s);
  assert(s.on && s.temp == 22 && s.load >= 27 && s.load <= 33);
  assert(mihome_mock_call("set_power", "[\"on\"]", buf, sizeof(buf)) > 0);
  assert(mihome_get(&h, &s) == 0 && s.temp == 20);
  show("raw set_power on", &s);
  assert(mihome_temp(&h, 25) == 0);
  sleep(21);
  assert(mihome_get(&h, &s) == 0);
  show("on +21 s", &s);
  assert(s.load >= 267 && s.load <= 273);

  /* Forced real without the config, and back */

  mihome_set_mode(MIHOME_REAL);
  assert(mihome_get(&h, &s) == -ENOENT && !h.mock && g_real_calls == 0);
  mihome_set_mode(MIHOME_MOCK);
  assert(mihome_get(&h, &s) == 0 && s.mock);
  printf("mode ok\n");
  mihome_close(&h);
  return 0;
}
