242	  char text[16];
243	
244	  /* The mock never looks like the real device */
245	
246	  lv_obj_set_style_bg_color(g_dot, lv_color_hex(mock ? UI_YELLOW :
247	                                                g_link_color[s->link]), 0);
248	  lv_label_set_text(g_link, mock ? "MOCK DEVICE" : g_link_text[s->link]);
249	  lv_obj_update_flag(g_badge, LV_OBJ_FLAG_HIDDEN, !mock);
250	  lv_obj_update_flag(g_via, LV_OBJ_FLAG_HIDDEN, mock);
251	  lv_obj_update_flag(g_note, LV_OBJ_FLAG_HIDDEN, s->link != AIRCON_NOCONF);
252	
253	  /* Values, or dashes while there are none */
254	
255	  lv_obj_update_flag(g_temp, LV_OBJ_FLAG_HIDDEN, !online);
256	  lv_obj_update_flag(g_degree, LV_OBJ_FLAG_HIDDEN, !online);
257	  lv_obj_update_flag(g_celsius, LV_OBJ_FLAG_HIDDEN, !online);
258	  lv_obj_update_flag(g_temp_none, LV_OBJ_FLAG_HIDDEN, online);
259	
260	  if (online)
261	    {
262	      snprintf(text, sizeof(text), "%d", s->dev.temp);
263	      ui_num_set(g_temp, text, anim && s->dev.temp != g_shown.dev.temp);
264	      snprintf(text, sizeof(text), "%d", s->dev.load);
265	      ui_num_set(g_load, text, anim && s->dev.load != g_shown.dev.load);
266	      lv_label_set_text(g_mode, s->dev.mode);
267	
268	      /* power only says what the partner sent by infrared, the load
269	       * says if the compressor runs
270	       */
271	
272	      lv_label_set_text(g_compressor, !on ? "OFF" :
273	                        s->dev.load >= s->dev.run_load ? "RUNNING" :
274	                        "WAITING");
275	
276	      aircon_after(g_degree, g_temp, 20, ui_ink_top(UI_OSWALD_300) + 4);
277	      aircon_after(g_celsius, g_temp, 80, ui_ink_top(UI_OSWALD_300) -
278	                   ui_ink_top(UI_OSWALD_120));
279	      /* No mock load in a curve of the real device and back */
280	
281	      if (s->dev.mock != g_shown_mock)
282	        {
283	          lv_chart_set_all_value(g_chart, g_series, LV_CHART_POINT_NONE);
284	          g_shown_mock = s->dev.mock;
285	        }
286	
287	      if (s->seq != g_shown.seq)
288	        {
289	          aircon_chart_add(s->dev.load);
290	        }
291	    }
292	  else
293	    {
294	      ui_num_set(g_load, "0", false);
295	      lv_label_set_text(g_mode, "--");
296	      lv_label_set_text(g_compressor, "--");
297	    }
298	
299	  lv_obj_update_flag(g_load, LV_OBJ_FLAG_HIDDEN, !online);
300	
301	  /* W on the baseline of the number */
302	
303	  aircon_after(g_watt, g_load, 16, lv_font_get_line_height(UI_OSWALD_120) -
304	               UI_OSWALD_120->base_line -
305	               lv_font_get_line_height(UI_OSWALD_64) +
306	               UI_OSWALD_64->base_line);
307	  lv_obj_update_flag(g_watt, LV_OBJ_FLAG_HIDDEN, !online);
308	
309	  /* Blue while on, the button shows what a tap does */
310	
311	  if (on != g_shown_on)
312	    {
313	      ui_anim(g_scr, aircon_bg_cb, on ? 0 : 255, on ? 255 : 0, 400, 0, NULL);
314	      lv_obj_set_style_bg_color(g_back, lv_color_hex(on ? UI_BLUE_DIM :
315	                                                     UI_INK_2), 0);
316	      lv_obj_set_style_bg_color(g_button, lv_color_hex(on ? 0xffffff :
317	                                                       UI_ORANGE), 0);
318	      lv_obj_set_style_text_color(g_icon, lv_color_hex(on ? UI_BLUE :
319	                                                       0xffffff), 0);
320	      g_shown_on = on;
321	    }
322	
323	  lv_obj_set_state(g_button, LV_STATE_DISABLED, !online || req != 0);
324	  lv_label_set_text(g_hint, req != 0 ? "SENDING" :
325	                            !online ? "" :
326	                            on ? "TAP TO TURN OFF" : "TAP TO TURN ON");
327	  lv_obj_align(g_hint, LV_ALIGN_TOP_MID, 0,
328	               AIRCON_BUTTON_Y + AIRCON_BUTTON_SIZE + 48);
329	
330	  g_shown = *s;
331	  g_shown_request = req;
332	}
