334	static void aircon_update_cb(lv_timer_t *timer)
335	{
336	  struct aircon_state_s s;
337	  int req;
338	
339	  UNUSED(timer);
340	
341	  pthread_mutex_lock(&g_lock);
342	  s = g_state;
343	  req = g_request;
344	  pthread_mutex_unlock(&g_lock);
345	
346	  if (s.seq != g_shown.seq || req != g_shown_request)
347	    {
348	      aircon_show(&s, req);
349	    }
350	}
