352	static void aircon_button_cb(lv_event_t *e)
353	{
354	  UNUSED(e);
355	
356	  pthread_mutex_lock(&g_lock);
357	  if (g_state.link == AIRCON_ONLINE && g_request == 0)
358	    {
359	      g_request = g_state.dev.on ? -1 : 1;
360	    }
361	
362	  pthread_mutex_unlock(&g_lock);
363	  aircon_update_cb(NULL);
364	}
