1	/****************************************************************************
2	 * app/aircon/aircon_main.c
3	 *
4	 * Air conditioner
5	 *
6	 * Power, mode, target temperature and load power of a Mi Home AC partner
7	 * on the LAN, with the load of the last two minutes and a button that
8	 * switches it on and off.  The page turns blue while the AC is on.
9	 *
10	 * A thread of its own talks miio to the device, every 2 s and at once
11	 * after a press.  The LVGL thread only shows what it last got, so a
12	 * device that does not answer never blocks the screen.
13	 ****************************************************************************/
14	
15	/****************************************************************************
16	 * Included Files
17	 ****************************************************************************/
18	
19	#include <nuttx/config.h>
20	
21	#include <sys/param.h>
22	
23	#include <ctype.h>
24	#include <errno.h>
25	#include <pthread.h>
26	#include <stdio.h>
27	#include <stdlib.h>
28	#include <string.h>
29	#include <unistd.h>
30	
31	#include <lvgl/lvgl.h>
32	
33	#include "lvx_ui.h"
34	#include "mihome.h"
35	
36	/****************************************************************************
37	 * Pre-processor Definitions
38	 ****************************************************************************/
39	
40	#define AIRCON_POLL           20      /* 100 ms steps between two polls */
41	
42	#define AIRCON_GREEN          0x51cf66
43	
44	#define AIRCON_STATUS_Y       263
45	#define AIRCON_TEMP_Y         400
46	#define AIRCON_MODE_Y         760
47	#define AIRCON_RULE_Y         950
48	#define AIRCON_LOAD_Y         1010
49	#define AIRCON_CHART_Y        1220
50	#define AIRCON_CHART_H        200
51	#define AIRCON_CHART_POINTS   60      /* 2 minutes */
52	#define AIRCON_BUTTON_Y       1500
53	#define AIRCON_BUTTON_SIZE    260
54	
55	/****************************************************************************
56	 * Private Types
57	 ****************************************************************************/
