59	enum aircon_link_e
60	{
61	  AIRCON_CONNECTING,
62	  AIRCON_NOCONF,
63	  AIRCON_OFFLINE,
64	  AIRCON_ONLINE
65	};
66	
67	/* What the thread last got, the values only count when online */
68	
69	struct aircon_state_s
70	{
71	  enum aircon_link_e link;
72	  unsigned int seq;         /* Counts the polls */
73	  struct mihome_state_s dev;
74	};
