90	/* Shared with the thread */
91	
92	static pthread_mutex_t g_lock = PTHREAD_MUTEX_INITIALIZER;
93	static struct aircon_state_s g_state;
94	static volatile int g_request;    /* 1 on, -1 off, 0 none */
95	static volatile bool g_running;
96	
97	/* LVGL thread only */
98	
99	static struct aircon_state_s g_shown;
100	static int g_shown_request;
101	static bool g_shown_on;
102	static bool g_shown_mock;
103	
104	static lv_obj_t *g_scr;
105	static lv_obj_t *g_back;
106	static lv_obj_t *g_dot;
107	static lv_obj_t *g_link;
108	static lv_obj_t *g_via;
109	static lv_obj_t *g_badge;
110	static lv_obj_t *g_note;
111	static lv_obj_t *g_temp;
112	static lv_obj_t *g_degree;
113	static lv_obj_t *g_celsius;
114	static lv_obj_t *g_temp_none;
115	static lv_obj_t *g_mode;
116	static lv_obj_t *g_compressor;
117	static lv_obj_t *g_load;
118	static lv_obj_t *g_watt;
