126	/****************************************************************************
127	 * Private Functions
128	 ****************************************************************************/
129	
130	/* Thread: store a poll, and drop the request it answered */
131	
132	static void aircon_publish(int ret, FAR const struct mihome_state_s *dev,
133	                           int req)
134	{
135	  FAR char *p;
136	
137	  pthread_mutex_lock(&g_lock);
138	  g_state.link = ret == 0 ? AIRCON_ONLINE :
139	                 ret == -ENOENT || ret == -EINVAL || ret == -ENOTSUP ?
140	                 AIRCON_NOCONF : AIRCON_OFFLINE;

140	                 AIRCON_NOCONF : AIRCON_OFFLINE;
141	  if (ret == 0)
142	    {
143	      g_state.dev = *dev;
144	      for (p = g_state.dev.mode; *p != '\0'; p++)
145	        {
146	          *p = toupper(*p);
147	        }
148	    }
149	
150	  if (req != 0 && g_request == req)
151	    {
152	      g_request = 0;
153	    }
154	
155	  g_state.seq++;
156	  pthread_mutex_unlock(&g_lock);
157	}
158	
159	static FAR void *aircon_thread(FAR void *arg)
160	{
161	  struct mihome_state_s dev;
162	  struct mihome_s h;
163	  int req;
164	  int ret;
165	  int i;
166	
167	  UNUSED(arg);
168	
169	  /* mihome opens the device on the first call, and again on every call
170	   * until that works, so a config put there later is picked up
171	   */
172	
173	  mihome_init(&h);
174	  while (g_running)
175	    {
176	      req = g_request;
177	      ret = req != 0 ? mihome_power(&h, req > 0) : 0;
178	      if (ret == 0)
179	        {
180	          ret = mihome_get(&h, &dev);
181	        }
182	
183	      aircon_publish(ret, &dev, req);
184	
185	      for (i = 0; i < AIRCON_POLL && g_running && g_request == 0; i++)
186	        {
187	          usleep(100 * 1000);
188	        }
189	    }
190	
191	  mihome_close(&h);
192	  return NULL;
193	}
